export const arAbout3: Record<string, string> = {
	'amrita-institute-of-medical-sciences-kochi':
		"##history\nتأسس مستشفى أمريتا في Ponekkara (كوتشي)، المعروف سابقًا بـAmrita Institute of Medical Sciences (AIMS)، في 17 مايو 1998 على يد ماتا أمريتاناندامايي ديفي (أما) كمستشفى إحالة متخصص وتعليمي متعدد التخصصات. حصل على جائزة FICCI الوطنية للتميز في الرعاية الصحية كأفضل مستشفى في البلاد عام 2013 وجائزتين أخريين من FICCI عام 2016 لسلامة المرضى والابتكار في التقنية الطبية. معتمد من NABH، ومختبراته معتمدة من NABL.\n##specialities\nيضم المستشفى 29 قسمًا متخصصًا و17 مركز تميز، بدعم من نحو 670 عضو هيئة تدريس و4,000 موظف دعم، ويخدم أكثر من مليون مريض عيادات خارجية وأكثر من 70,000 حالة دخول سنويًا. من الإنجازات أول زراعة متزامنة للبنكرياس والكلى في كيرالا (2014)، وأول زراعة يدين ثنائية في جنوب آسيا (2015)، وفي 2021 أول زراعة لكلا الطرفين العلويين باستخدام تقنية HEMO2life للحفاظ على الطعم، وهي التاسعة من نوعها للمستشفى. تمتد الخدمات من طب نقل الدم والمسالك البولية إلى جراحة الوجه والفكين والجمجمة والجلدية والتجميل.\n##technology\nيضم المستشفى بين 1,100 و1,450 سريرًا وفقًا لمصادر مختلفة، مما يجعله أحد أكبر المستشفيات في جنوب الهند. يقع على حرم واسع في Ponekkara، كوتشي.\n##international\nيضم أمريتا فريقًا مخصصًا ينسق علاج المرضى الدوليين، بدعم في التأشيرة الطبية والإقامة، وآراء طبية قبل الزيارة بشأن العلاج والتكلفة، ومترجمين فوريين متعددي اللغات.",
	'aster-medcity':
		"##history\nأسست Aster DM Healthcare مستشفى أستر مدسيتي في Cheranalloor (كوتشي) عام 2013 وبدأ التشغيل التجريبي عام 2014. يقع على حرم بمساحة 40 فدانًا على ضفاف بحيرات كوتشي وهو أحد أكبر مراكز الرعاية الفائقة التخصص في جنوب آسيا. كان أول مستشفى متعدد التخصصات للرعاية الفائقة معتمد من JCI في كيرالا، وفي عامه الأول حصل أيضًا على اعتماد NABH وشهادة التميز في التمريض NABH وشهادة Green OT.\n##specialities\nأستر مدسيتي مستشفى متعدد التخصصات بثمانية مراكز تميز، تشمل الأعصاب وعلوم القلب وجراحة العظام والأورام وأمراض الجهاز الهضمي وأمراض الكلى والمسالك البولية وصحة المرأة وطب الأطفال وحديثي الولادة وزراعة الأعضاء المتعددة. يتولى فريق زراعة متعدد التخصصات من أطباء الكبد والكلى وجراحي الزراعة وأطباء العناية المركزة إجراء زراعات الكلى والكبد والقلب والزراعات المشتركة. يُقال إنه كان أول مستشفى في كيرالا يقدم الجراحة الروبوتية طفيفة التوغل بنظام دا فينشي، مع أكثر من 5,000 جراحة مدعومة بالروبوت في الزراعة والمسالك البولية وأمراض النساء.\n##technology\nالمستشفى منشأة كبيرة للرعاية الفائقة بعدة مئات من الأسرّة؛ تذكر المصادر نحو 670 إلى 800. صُمم حرمه مراعاةً لراحة المرضى، ويحمل شهادة خضراء.\n##international\nأستر مدسيتي وجهة معروفة للمسافرين الطبيين من جنوب الهند. تقع Cheranalloor بالقرب من مدينة كوتشي وعلى بُعد نحو 25 إلى 30 كم من مطار كوتشين الدولي.",
	'lakeshore-hospital':
		"##history\nمستشفى VPS Lakeshore في Nettoor (كوتشي)، على الطريق الالتفافي NH-66، مستشفى فائق التخصص بدأ العمل كمستشفى متعدد التخصصات في يناير 2003. معتمد من NABH ويُوصف بأنه وجهة رائدة للسياحة الطبية. حصل على جائزة أفضل مستشفى للسياحة الطبية من حكومة كيرالا عام 2014، وجائزة أفضل مستشفى في كيرالا من Worldwide Achievers عام 2016، وجائزة أفضل مستشفى لخدمات الأورام من Times of India عام 2017.\n##specialities\nيضم المستشفى أكثر من 30 قسمًا سريريًا، بما فيها زراعة الأعضاء المتعددة وأمراض الجهاز الهضمي واستبدال المفاصل وأمراض القلب وجراحة الأوعية القلبية والأعصاب. أجرى قسم أمراض الكلى وزراعتها أكثر من 1,600 عملية زراعة، ويضم مركز علوم القلب زراعة القلب وECMO. من الإنجازات أول زراعة كبد في كيرالا، وأول زراعة نخاع عظم للأطفال، وأول نظام روبوتي لاستبدال الركبة في الولاية، وأول خدمة إسعاف جوي ومائي وبري في كيرالا، معترف بها من Limca Book of Records.\n##technology\nيضم المستشفى عدة مئات من الأسرّة، تذكر المصادر نحو 470 إلى 650، وهو رائد في زراعة الأعضاء ورعاية القلب والجراحة طفيفة التوغل.\n##international\nيقدم المستشفى خدمات استقبال ضيوف على مدار الساعة، وخيارات دفع مسبق للمرضى الدوليين، ومأكولات مخصصة، وموظفين متعددي اللغات، وقبول العملات الأجنبية.",
	'kims-health-kochi':
		"##history\nKIMS Health، Kochi، هو مستشفى كوتشي التابع لمجموعة مؤسسات KIMS ومقرها تيروفانانثابورام، والتي لها أيضًا مستشفيات في الشرق الأوسط. يقع مستشفاه ومركزه الجراحي في Pathadipalam، Changampuzha Nagar Post، Edappally، ويهدف إلى تقديم رعاية صحية عالمية المستوى بتكلفة معقولة. معتمد من NABH ومن المجلس الأسترالي لمعايير الرعاية الصحية الدولية (ACHSI).\n##specialities\nالمستشفى منشأة متعددة التخصصات بسعة 125 سريرًا ونحو 25 قسمًا يغطي أمراضًا وحالات مختلفة. يقدم أقسام العيادات الخارجية والداخلية والمختبر والصيدلية والأشعة السينية وتخطيط القلب وخدمات على مدار الساعة، بدعم من استشاريين ذوي خبرة وممرضين مدربين وطاقم شبه طبي.\n##technology\nالمستشفى حديث ومجهز جيدًا لحجمه. مقارنةً بأكبر مستشفيات كوتشي، إنها منشأة أصغر، لذا قد يجد المرضى ذوو الاحتياجات المعقدة جدًا، مثل زراعة الأعضاء المتعددة، خدمة أفضل في مكان آخر.\n##international\nEdappally منطقة نشطة في كوتشي بالقرب من مركز Lulu Mall التجاري ومحطة سكة حديد Edappally. يجعل موقعه العملي وحجمه المتوسط المستشفى مناسبًا للمرضى الذين يحتاجون إجراءات عامة أو مخططة في بيئة مريحة.",
	'apollo-multispeciality-hospitals-kolkata':
		"##history\nتأسس مستشفى أبولو متعدد التخصصات، المعروف سابقًا بأبولو غلينيغلز، على طريق Canal Circular Road بكولكاتا عام 2003، وهو مستشفى للرعاية المتخصصة بسعة 700–750 سريرًا. إنه المستشفى الوحيد في شرق الهند المعتمد من JCI. صنّفه استطلاع The Week–Hansa Research كأفضل مستشفى خاص في شرق وشمال شرق الهند لمدة 12 عامًا متتاليًا، وفاز بجائزة أفضل مستشفى متعدد التخصصات في شرق الهند في جوائز Global Health and Travel لعام 2019.\n##specialities\nيضم المستشفى أكثر من 50 تخصصًا و33 مركز تميز، بما فيها رعاية القلب ورعاية السرطان وجراحة العظام وأمراض الجهاز الهضمي والأعصاب وزراعة الأعضاء والجراحة الروبوتية والطوارئ. أجرى أول زراعة متزامنة للقلب والكبد والكلى في شرق الهند، وجلب إلى المنطقة زراعة الكلى الروبوتية الكاملة؛ وأجرت مجموعة أبولو أكثر من 10,000 زراعة كلى. إنه أيضًا اسم موثوق لزراعة نخاع العظم للمرضى الدوليين.\n##technology\nيتعامل المستشفى مع أكثر من 1,600 زيارة عيادة خارجية يوميًا، ويضم مراكز زراعة مجهزة لجراحات المتبرع الحي والمتوفى.\n##international\nيتلقى أكثر من 10,000 مريض دولي سنويًا، كثير منهم من بنغلاديش، العلاج في أبولو كولكاتا، الذي يضم فريقًا مخصصًا لخدمات المرضى الدوليين. يقع في منطقة Kankurgachi بكولكاتا.",
	'amri-hospitals-dhakuria':
		"##history\nبدأت AMRI Hospitals، Dhakuria، عام 1996 كمشروع شراكة بين القطاعين العام والخاص مع حكومة West Bengal، أولًا كمنشأة عيادات خارجية، ثم توسعت لتصبح مستشفى بسعة 150 سريرًا عام 1997 وتوسعت لاحقًا إلى عدة مئات من الأسرّة. استحوذت Manipal Hospitals على حصة الأغلبية في مجموعة AMRI عام 2023، ومستشفى Dhakuria هو الآن Manipal Hospital Dhakuria (سابقًا AMRI)، مع وجود Manipal في Salt Lake وDhakuria وMukundapur وBroadway بكولكاتا. تحت علامة AMRI، سُمّي أفضل مستشفى خاص في شرق الهند في جوائز ABP News Healthcare Leadership عامي 2020 و2021.\n##specialities\nيُعرف المستشفى بعلوم القلب واستبدال المفاصل ورعاية الصدمات وأطفال الأنابيب وجراحة الوجه والفكين والجراحة التجميلية والتجميلية. خدمات الطوارئ والرعاية الحرجة فيه مركز تميز. في 2024، حصل على جوائز في Economic Times Healthcare Awards عن مساهمته في رعاية الطوارئ والتميز في الأعصاب وإدارة السكتة الدماغية، وكُرّم من حكومة بنغلاديش لخدمته للمرضى البنغلاديشيين.\n##technology\nيشمل التصوير النووي المتقدم PET-CT وSPECT-CT، ويشمل العلاج الإشعاعي IMRT وVMAT. المستشفى معتمد من NABH. يقع على طريق Gariahat Road، Dhakuria، جنوب كولكاتا.\n##international\nتقدم Manipal Hospitals خدمات مخصصة للمرضى الدوليين، بما فيها الآراء الطبية وتخطيط العلاج والمساعدة في السفر والدعم الشخصي.",
	'fortis-hospital-anandapur':
		"##history\nتأسس مستشفى فورتيس، Anandapur، بكولكاتا عام 2011 ويمتد على نحو سبعة أفدنة على طول Eastern Metropolitan Bypass. إنه مبنى من 10 طوابق بسعة نحو 300 سرير، منها نحو 240 سريرًا تشغيليًا. من الإنجازات أول استبدال ركبة مصنوع حسب الطلب في شرق الهند (2011)، وأول عملية فتح قحف والمريض مستيقظ في شرق الهند (2012)، وإطلاق أول فريق قلب في الهند (2012)، وزراعة كلى لطفل يزن أقل من 12 كجم (2014). حصل على لقب Times Bengal Icons 2023 كأفضل منشأة لرعاية الصدمات في المدينة وجوائز في CAHOCON 2024.\n##specialities\nيتخصص المستشفى في أمراض القلب وجراحة القلب والمسالك البولية وأمراض الكلى والأعصاب وجراحة العظام والرعاية الهضمية والطب التنفسي ورعاية الأم والطفل والطوارئ والرعاية الحرجة. يضم أيضًا عيادات متخصصة في ارتفاع ضغط الدم الرئوي والتهوية غير التداخلية والحساسية، ويقدم الأورام وجراحة الوجه والفكين وطب الأسنان والطب النفسي والسكري والجلدية وأنف وأذن وحنجرة. يضم مركزه القلبي أربعة مختبرات قسطرة وغرفة عمليات قلبية وSICU بـ14 سريرًا وCCU بـ20 سريرًا.\n##technology\nيحمل المستشفى اعتماد NABH وشهادة NABL.\n##international\nكجزء من فورتيس هيلث كير، يدعم المستشفى المرضى الدوليين من خلال الخدمات الدولية للمجموعة. يقع في Anandapur، على EM Bypass، بموقع مريح للأحياء التجارية والمطار.",
	'medica-superspecialty-hospital':
		"##history\nأُطلق مستشفى ميديكا سوبر سبيشياليتي في Mukundapur عام 2010 وهو جزء من مجموعة ميديكا، التي تُوصف بأنها أكبر سلسلة مستشفيات في شرق الهند. إنه مستشفى للرعاية المتخصصة بعدة مئات من الأسرّة، بـ18 قسمًا وثمانية مراكز تميز، في 127 Eastern Metropolitan Bypass. في فبراير 2022، ركّب روبوت دا فينشي من الجيل الرابع، ليصبح أول مركز تدريب رسمي للجراحة الروبوتية في شرق الهند. كما أنه أول مستشفى في شرق الهند يحمل غرفة عمليات خضراء معتمدة، وحصل على Times Bengal Award عام 2023.\n##specialities\nيغطي المستشفى التخدير وأمراض القلب وجراحة القلب والرعاية الحرجة والجلدية وطب الأسنان وطب الطوارئ والغدد الصماء وأنف وأذن وحنجرة وأمراض الجهاز الهضمي والجراحة العامة والهضمية وأمراض الدم وأمراض الكبد وأمراض الكلى والأعصاب وجراحة الأعصاب وطب الأنف والأذن العصبي والطب النووي وجراحة العظام والتوليد وأمراض النساء والأورام وجراحة الأطفال والجراحة التجميلية والترميمية وإعادة التأهيل والطب النفسي والأشعة والطب التنفسي وأمراض الروماتيزم والجراحة الروبوتية وطب نقل الدم والمسالك البولية.\n##technology\nيضم ميديكا إحدى أكثر وحدات الرعاية الحرجة تقدمًا في المنطقة، ومختبرًا معتمدًا من NABL بمختبر جزيئي، وخدمات تصوير تلبي المعايير الدولية. اعتُمد مركز غسيل الكلى فيه عام 2020 وفاز بجائزة أفضل مزود لخدمات غسيل الكلى. المستشفى معتمد من NABH وNABL.\n##international\nيقدم ميديكا خدمات للمرضى الدوليين وهو وجهة معروفة لمرضى الدول المجاورة.",
	'zydus-hospitals':
		"##history\nمستشفيات زيدوس في أحمد آباد مبادرة تابعة لمجموعة زيدوس، افتُتحت عام 2015 على S. G. Highway بالقرب من Sola Bridge. إنها مستشفى فائق التخصص بسعة 550 سريرًا على 16 طابقًا وطابقين تحت الأرض، معتمد من NABH وNABL. تم تكريمه كأفضل مستشفى في أحمد آباد وفق استطلاع The Week–Marg لأربع سنوات وكان المستشفى الثامن عشر في غوجارات الفائز بجائزة Global Green-OT. عيّن المستشفى متخصصين طبيين مدربين في الولايات المتحدة وأوروبا.\n##specialities\nزيدوس مركز للأعصاب والرعاية الهضمية والمسالك البولية وأمراض النساء والأورام والعمود الفقري والجراحة التجميلية والتجميلية وأمراض الكلى وأنف وأذن وحنجرة، بمراكز تميز في أطفال الأنابيب واستبدال المفاصل ورعاية السرطان والأعصاب وجراحة القلب وزراعة الكلى وزراعة الكبد وجراحة الأعصاب والجراحة التجميلية. يدعم برنامج زراعة الكبد فريق متعدد التخصصات يضم أكثر من 20 متخصصًا، وأجرى في مراكزه بأحمد آباد وفادودارا أكثر من 430 زراعة كلى، وأكثر من 295 زراعة كبد، وأكثر من 220 زراعة نخاع عظم.\n##technology\nيجمع المستشفى بين غرف عمليات حديثة وتصوير متقدم وقدرة كبيرة للرعاية الحرجة مع ممارسات البناء الأخضر.\n##international\nبرزت أحمد آباد كوجهة رئيسية في غرب الهند، ويجذب زيدوس حصة متزايدة من المرضى الدوليين؛ كما يدير أطباؤه معسكرات صحية في دول أفريقية وأوزبكستان.",
	'cims-hospital':
		"##history\nافتتح مستشفى CIMS، المعروف الآن بمستشفى مارينغو آسيا CIMS، عام 2010 بالقرب من طريق Science City Road، في Sola (أحمد آباد)، وهو جزء من مجموعة مارينغو آسيا هيلث كير. إنه مستشفى أخضر فائق التخصص معتمد من NABH وNABL وJCI. في أكتوبر 2023، أجرى فريقه بقيادة الدكتور ضيرين شاه ما يُقدَّم كأول زراعة قلب بلا نقل دم في آسيا، باستخدام بروتوكول لإدارة النزيف موجه بالأهداف؛ خرجت المريضة بعد تسعة أيام مقارنةً بـ21 إلى 24 يومًا المعتادة.\n##specialities\nيقدم المستشفى رعاية السرطان وعلوم القلب وأمراض الجهاز الهضمي وزراعة الكبد وعلوم القنوات الصفراوية وجراحة العظام واستبدال المفاصل وعلوم الكلى والأعصاب وزراعة نخاع العظم وجراحة السمنة وعلم النفس السريري وأمراض الروماتيزم والقدم السكرية وطب الأسنان والجلدية. الدكتور ضيرين شاه، مدير برنامج زراعة القلب وأول جراح زراعة قلب في غوجارات، أجرى أكثر من 16,000 عملية مجازة تاجية ونحو 50 زراعة قلب، وكان الأول في الهند الذي أجرى TAVR عبر الأبهر والمجازة الهجينة. يضم المستشفى مركزًا مخصصًا للزراعة للقلب والكبد والكلى والرئة وزراعة نخاع العظم للأطفال.\n##technology\nيُوصف المستشفى بأنه منشأة بـ300–500 سرير، مقابل Shukan Mall، بعناية مركزة وغرف عمليات متقدمة.\n##international\nيعالج المستشفى مرضى من الهند والخارج.",
	'sterling-hospital':
		"##history\nتأسست مستشفيات ستيرلينغ في Gurukul، Memnagar (أحمد آباد)، عام 2001 كمستشفى للرعاية المتخصصة وتطورت إلى شبكة مستشفيات في جميع أنحاء غوجارات. في 2009، أصبح أول مستشفى في غوجارات معتمد بالكامل من NABH، وكانت مختبراته أول من اعتمدتها NABL في الولاية. سُمّي أفضل مستشفى لثلاث سنوات متتالية (2007 إلى 2009) من IMRB وThe Week.\n##specialities\nتقدم ستيرلينغ علوم القلب والأورام (جراحية وطبية وإشعاعية) والرعاية الحرجة والطب التنفسي وأمراض الجهاز الهضمي وجراحة الجهاز الهضمي والأعصاب وجراحة العمود الفقري وأمراض الكلى والمسالك البولية وجراحة العظام واستبدال المفاصل والتوليد وأمراض النساء وأمراض الدم ورعاية الصدمات وجراحة السمنة وأنف وأذن وحنجرة والتخدير. أجرت أول زراعة كبد في المنطقة، وأدخلت غسيل الكلى CRRT، وأنشأت أول وحدة نخاع عظم في غوجارات وأكبر منشأة لغسيل الكلى في الولاية. تُعرف كمركز قلب رائد في أحمد آباد.\n##technology\nيضم المستشفى نحو 300 سرير. وحداته للعناية المركزة للأطفال وحديثي الولادة مجهزة بمراقبة متعددة المعايير وأجهزة تنفس وECMO ونسبة عالية من الممرضين إلى المرضى.\n##international\nتفيد ستيرلينغ بعلاج أكثر من 20,000 مريض دولي سنويًا من أكثر من 130 دولة، من خلال خدمة موحدة للمرضى الدوليين تنسق بين المستشفى والأطباء والمرضى.",
	'shalby-hospitals':
		"##history\nبدأت مستشفيات شالبي في أحمد آباد عام 1994 كمركز لاستبدال المفاصل أسسه الدكتور فيكرام آي. شاه، وفي نحو 30 عامًا أصبحت واحدة من أسرع سلاسل المستشفيات متعددة التخصصات نموًا في الهند في الغرب والوسط والشمال. يقع المستشفى الرائد في أحمد آباد، Shalby Multispeciality Hospital، على S. G. Highway بالقرب من Ramdev Nagar، Satellite، وتأسس عام 2007. يرأس الدكتور شاه شالبي ويقود برنامج استبدال المفاصل فيها منذ 1993، وحصل على جائزة الدكتور بي سي روي الدولية عام 2003. في 2025، حصلت المجموعة على جائزة Hurun India Healthcare Transformation and Medical Excellence وجائزة أفضل مستشفى للسياحة الطبية في غوجارات.\n##specialities\nتشتهر شالبي عالميًا باستبدال المفاصل، بأكثر من 150,000 عملية استبدال. يجري الدكتور شاه وفريقه أكثر من 800 عملية استبدال مفصل أولية شهريًا، وقلّصت تقنيته ZERO مدة عملية استبدال الركبة الجراحية من نحو 80 دقيقة إلى نحو 10–12 دقيقة. حصلت المجموعة أيضًا على جائزة Rajiv Gandhi National Quality وجوائز FICCI.\n##technology\nمستشفى SG Highway معتمد من NABH وNABL، بنحو 200 سرير.\n##international\nتضم شالبي مكتبًا خاصًا للمرضى الدوليين يقدم استشارات فيديو ومساعدة في السفر والتأشيرة ودعم الإقامة، والاستقبال والمغادرة المجانية من المطار.",
	'dr-agarwal-s-eye-hospital':
		"##history\nتأسس مستشفى الدكتور أغاروال للعيون عام 1957 في تشيناي على يد بادما بهوشان الدكتور جايفير أغاروال والدكتورة طاهرة أغاروال. حصل الدكتور جايفير أغاروال على بادما بهوشان في مارس 2006. عبر العقود، أصبح إحدى أكبر سلاسل رعاية العيون في الهند، بمراكز في 14 ولاية وأربعة أقاليم اتحادية وعدة دول بالخارج، خاصةً في أفريقيا. يختلف العدد الدقيق للمراكز حسب المصدر ويتغير بمرور الوقت، لذا يجب على المرضى التحقق من القائمة الحالية لمواقع Delhi-NCR عند التخطيط.\n##specialities\nيقدم المستشفى طب عيون شاملًا، بما فيه جراحة إعتام العدسة بتقنيات مثل تفتيت العدسة والمساعدة بالليزر الفيمتوثاني، والليزك وجراحات الانكسار الأخرى، ورعاية الشبكية لحالات مثل اعتلال الشبكية السكري وانفصال الشبكية، والزَرَق والقرنية وطب عيون الأطفال. ترتبط المجموعة أيضًا بجراحين وباحثين معروفين في طب العيون، بمن فيهم الدكتور أمر أغاروال، المعروف بابتكاراته في جراحة إعتام العدسة.\n##technology\nتُجرى معظم إجراءات العيون كرعاية نهارية، وهو أمر عملي للزوار الدوليين. يضم Delhi-NCR عدة مراكز Dr. Agarwal's.\n##international\nنظرًا لأن العديد من إجراءات العيون تتطلب إقامة قصيرة فقط، غالبًا ما يستطيع المرضى الجمع بين العلاج والسفر في المنطقة.",
	'laimaa-fertility-ivf-surrogacy-clinic':
		"##history\nتأسست Laimaa Fertility عام 2022 على يد فريق من أخصائيي الأجنة والأطباء ذوي الخبرة، وتقع في E-580، Greater Kailash Part II، نيودلهي. نشأت بقيادة أخصائية الأجنة بوجا أغاروال والدكتورة أكانكشا تشوهان والدكتورة ممتا تشاهار، مع الدكتور فينيت مالهوترا أيضًا في الفريق، بالجمع بين الخبرة الطبية والمخبرية. بدأت أخصائية الأجنة بوجا أغاروال مسيرتها في Fortis Ridge IVF Centre وقادت مختبرات أطفال الأنابيب في عدة مؤسسات، منها في غوروغرام ونويدا، وهي أخصائية أجنة معتمدة لخزعة الأجنة.\n##specialities\nتقدم العيادة أطفال الأنابيب وICSI وIUI وتجميد البويضات والأجنة والتبرع بالبويضات وخطط أدوية مخصصة وإجراءات جراحية طفيفة التوغل للعقم والعلاج الهرموني. تُعرف بعملها في الحالات الصعبة مثل انخفاض AMH وعقم الذكور الشديد، ويُجري فريقها للأجنة TESA-ICSI وPICSI ونقل الكيسة الأريمية وتجميد البويضات والأجنة. غالبًا ما يشيد المرضى بالدكتورة أكانكشا تشوهان لطيبتها ومعرفتها وتوفرها.\n##technology\nتستخدم العيادة تقنيات إنجابية متقدمة وتؤكد على الرعاية الشخصية والممارسة الأخلاقية. كعيادة أحدث، تعمل كمركز خصوبة مركّز بمختبر أجنة داخلي.\n##international\nتقدم العيادة استشارات بالإنجليزية والهندية. Greater Kailash Part II منطقة جيدة الخدمات في South Delhi، بفنادق وإمكانية وصول بالمترو.",
	'gaudium-ivf':
		"##history\nتأسست Gaudium IVF and Women Health عام 2009 على يد الدكتورة مانيكا خانا، أخصائية عقم وجراحة منظارية معترف بها عالميًا، بخبرة تفوق 20 عامًا في علاج الخصوبة. حصلت على جائزة Delhi Ratan عام 2008 من رئيس الهند آنذاك، وكُرّمت بجوائز منها Rajiv Gandhi Excellence Award وWomen Achievers' Award. تضم Gaudium اليوم نحو 36 مركزًا في ست ولايات هندية ومراكز في دول أخرى، وتفيد بولادة أطفال Gaudium أصحاء في أكثر من 30 دولة.\n##specialities\nيقدم المركز أطفال الأنابيب وتجميد البويضات وتجميد الأجنة، ويُعرف بعلاج فشل أطفال الأنابيب المتكرر وعقم الذكور والانتباذ البطاني الرحمي والحمل عالي الخطورة. تفيد الدكتورة خانا بإجراء أكثر من 10,000 علاج أطفال أنابيب باسمها، وتُوصف عيادات المجموعة بأنها عيادات فائقة التخصص برعاية متعددة التخصصات وأخصائيي أجنة ذوي خبرة.\n##technology\nيستخدم نظام علم الأجنة في Gaudium أدوات قائمة على الذكاء الاصطناعي، بما فيها SiD لتقييم الحيوانات المنوية وERICA لتقييم الأجنة، في قلب إطار Signature Lab الذي يجمع بين علم الأجنة المتقدم ومعايير الجودة المرجعية الدولية. تقع عيادة دلهي في M-1، الطابق الأول، South Extension Part 2.\n##international\nعالجت Gaudium أزواجًا من أكثر من 30 دولة. South Extension منطقة تجارية نشطة في South Delhi، بارتباط جيد بالمترو.",
	'pristyn-care-ferticity-super-speciality-ivf-hospital':
		"##history\nيقع مستشفى Pristyn Care Ferticity للرعاية الفائقة وأطفال الأنابيب في 12، Navjeevan Vihar، Geetanjali Enclave، Malviya Nagar، نيودلهي، ويفيد بمساعدة أكثر من 40,000 عائلة حول العالم. المؤسسة المشاركة والمديرة، الدكتورة إيلا غوبتا، تتمتع بأكثر من 29 عامًا من الخبرة في علاج العقم وتقنيات الإنجاب المساعد، عالجت أكثر من 5,500 حالة معقدة، وحصلت على جائزة الدكتور عبد الكلام الصحية عام 2023. العيادة مدرجة في سجل عيادات ART التابع لـICMR.\n##specialities\nصُمم المستشفى للأزواج الباحثين عن أطفال الأنابيب وIUI وICSI وتجميد البويضات والأجنة والعلاج بالمتبرعين. يدير متلازمة تكيس المبايض وانسداد قناة فالوب وانخفاض المخزون المبيضي وعقم الذكور والانتباذ البطاني الرحمي والإجهاض المتكرر، ويقدم تحفيز الإباضة وتقييمًا هرمونيًا وإنجابيًا مفصلًا. تفيد الدكتورة غوبتا بمعدلات نجاح تصل إلى 78٪ باستخدام تقنيات مثل العلاج بالبلازما الغنية بالصفائح والفحص الجيني، رغم اختلاف النتائج من مريض لآخر.\n##technology\nجميع أخصائيي الخصوبة مسجلون لدى مجلس الطب، وتعمل العيادة كمستشفى فائق التخصص وأطفال أنابيب بمرافق جراحية ومختبر أجنة ودعم استشاري. تفتح من الاثنين إلى السبت.\n##international\nعالجت العيادة أزواجًا دوليين، بمن فيهم مرضى سافروا من الولايات المتحدة لأطفال الأنابيب مع الدكتورة غوبتا. Malviya Nagar قريبة من محطة مترو Malviya Nagar، في South Delhi.",
	'nova-ivf-fertility-centre-rajouri-garden':
		"##history\nمركز Nova IVF Fertility في Rajouri Garden إحدى عيادات المجموعة في دلهي، في GN-14، Shivaji Enclave، Sector G، Mehta Chowk، بالقرب من محطة مترو Rajouri Garden. تأسست Nova IVF Fertility عام 2011، وحصلت المجموعة على جائزة أفضل سلسلة أطفال أنابيب في الهند في جوائز ET Healthworld الوطنية للخصوبة 2021 وجائزة بطل العام لأطفال الأنابيب/الخصوبة عام 2025. تفيد المجموعة بأكثر من 85,000–100,000 ولادة حية بأطفال الأنابيب في شبكتها.\n##specialities\nتقدم العيادة IUI وأطفال الأنابيب وICSI واختيار الحيوانات المنوية بتقنية MACS وتجميد البويضات وبرامج المتبرعين وتشخيصًا متقدمًا، وتعالج عقم الذكور والعقم غير المبرر وانخفاض المخزون المبيضي ومتلازمة تكيس المبايض والانتباذ البطاني الرحمي والعقم بسبب قناة فالوب. الدكتورة أسواتي نائر أخصائية أطفال أنابيب أكملت MBBS في مومباي وMD في التوليد وأمراض النساء، ثم FNB في طب الإنجاب، بخبرة تفوق 17 عامًا. فازت بجائزة أفضل ورقة بحثية في فرع كيرالا لـISAR عن بحثها حول غراء الأجنة في فشل الانغراس المتكرر. تمارس الدكتورة ميناكشي بانرجي، أخصائية أمراض نساء بخبرة تفوق 20 عامًا، هنا أيضًا.\n##technology\nمثل عيادات Nova IVF الأخرى في Delhi NCR، تضم مختبر أجنة متقدمًا وغرفة عمليات حديثة ومنطقة تعافٍ مريحة، وفق بروتوكولات دولية. تفتح العيادة من الاثنين إلى السبت.\n##international\nترتبط Rajouri Garden جيدًا بالمترو مع وسط دلهي وخط المطار.",
	'elixir-fertility-centre':
		"##history\nتأسس Elixir Fertility Centre عام 2014، وهو عيادة أطفال أنابيب وخصوبة في شمال دلهي، في Vardhman Royal Plaza، Plot 5، LSC Gujranwala Town-1. يهدف إلى الجمع بين خبراء عقم ذوي خبرة وتقنية متقدمة لتحسين معدلات النجاح، وتدرب أخصائيو أطفال الأنابيب وأخصائيو الأجنة فيه في مراكز رائدة بالمملكة المتحدة وألمانيا وسنغافورة والهند.\n##specialities\nتقدم العيادة أطفال الأنابيب وICSI وIUI وتحليل السائل المنوي والفحص الجيني. يضم الفريق الدكتور بونيت كوتشار، أخصائي أطفال أنابيب عمل سابقًا في Bourn Hall Clinic بكامبريدج، المملكة المتحدة، ودرّس في Lady Hardinge Medical College بدلهي؛ والدكتور براناي غوش، المدير واستشاري الخصوبة، الذي تدرب في مراكز منها NURTURE في نوتنغهام وNUH CREST في سنغافورة وCentre of Reproductive Medicine في كيل، وأكمل ماجستيرًا بريطانيًا بامتياز؛ والدكتور راجيف سينغلا، أخصائي الغدد الصماء الإنجابية؛ والدكتورة تيتا غوش، أخصائية جينات سريرية ومناعة إنجابية.\n##technology\nتضم العيادة مختبر تشخيص وموجات فوق صوتية وخدمة طوارئ وموقف سيارات، وتعمل من الاثنين إلى السبت من نحو 9 صباحًا إلى 6 مساءً. تفيد بمعدلات نجاح لأطفال الأنابيب بين 65 و75٪، تختلف حسب ظروف كل شخص.\n##international\nGujranwala Town في شمال دلهي قريبة من Model Town وKamla Nagar، ويمكن الوصول إليها بالمترو من وسط دلهي.",
	'femmenest-fertility-ivf-centre':
		"##history\nFemmenest مركز راقٍ لصحة المرأة في شرق دلهي يقدم أطفال الأنابيب والعقم وأمراض النساء، في C-52 UGF، Anand Vihar، مقابل Pushpanjali Medical Centre. يرأس المركز الدكتورة سوجانيا أغاروال، أخصائية أطفال أنابيب وجراحة منظارية وروبوتية لأمراض النساء بخبرة سريرية تفوق 20 عامًا. أكملت MS في التوليد وأمراض النساء في Sri Ramachandra University بتشيناي، تلتها زمالة في جراحة أمراض النساء طفيفة التوغل وطب الإنجاب في كوتشي، وحصلت على Dr. Jagdishwari Mishra Oration Award عام 2012.\n##specialities\nيقدم المركز أطفال الأنابيب وIUI وICSI، ودعمًا شخصيًا للأزواج، ورعاية شاملة للعقم من التشخيص إلى العلاجات الهرمونية، ورعاية متقدمة لأمراض النساء لمتلازمة تكيس المبايض والاختلالات الهرمونية ومشاكل الخصوبة والفحوصات الصحية الروتينية للمرأة، إلى جانب طب الجنين. يضم فريقًا من كبار الأطباء وأخصائيي الأجنة السريريين وموظفي دعم وممرضات مخصصات.\n##technology\nالمركز مجهز بمرافق حديثة لرعاية شاملة للمرأة. يفتح عادةً من الاثنين إلى السبت من 9 صباحًا إلى 8 مساءً وصباح الأحد، ويحصل على تقييمات عالية جدًا من المرضى.\n##international\nترتبط Anand Vihar جيدًا بالمترو ومحطة Anand Vihar للسكك الحديدية والحافلات، وهو أمر مريح للمسافرين القادمين من مدن أخرى.",
	'india-ivf-clinic':
		"##history\nIndia IVF Clinic في Vasant Vihar عيادة خصوبة تابعة لشبكة فورتيس. تمارس الاستشارات في Fortis Flt. Lt. Rajan Dhall Hospital في Vasant Kunj، ومدرجة في العنوان 35، Second Floor، Community Centre، Basant Lok، Vasant Vihar. تعمل في مجال الرعاية الصحية منذ نحو 12 عامًا وتحصل على تقييمات عالية جدًا من المرضى.\n##specialities\nتقود الدكتورة ريتشيكا ساهاي فريق الخصوبة. تتمتع بأكثر من 20 عامًا من الخبرة كأخصائية خصوبة وجراحة منظارية لأمراض النساء، وهي أخصائية غدد صماء إنجابية معتمدة وأخصائية فرعية في العقم (أطفال الأنابيب-ICSI)، تخرجت من كلية الطب بميدالية ذهبية وحصلت على جائزة أفضل أخصائية شابة لأطفال الأنابيب عام 2018. تشمل مجالات خبرتها أطفال الأنابيب وICSI وتجميد البويضات والأجنة وتحفيز الإباضة وIUI والفحص والاختبار الجيني قبل الانغراس وإدارة الحمل والإجهاض. تتبنى نهجًا شاملاً، مع الاهتمام بالتغذية ونمط الحياة والبيئة.\n##technology\nالعيادة يمكن الوصول إليها بكرسي متحرك وتضم موقف سيارات. يصف المرضى الموظفين بأنهم ودودون ومهتمون وداعمون، ويذكرون حالات حمل وولادة ناجحة.\n##international\nنظرًا لأن الفريق يعمل أيضًا في Fortis Vasant Kunj، بالقرب من المطار الدولي، يمكن للأزواج الدوليين الجمع بين استشارات الخصوبة ومستشفى متعدد التخصصات مجهز جيدًا.",
	'spruce-dental':
		"##history\nSpruce Dental في Jasola Vihar (South Delhi) جزء من مجموعة عيادات Spruce Dental، التي يقودها أخصائي الزراعة وتقويم الأسنان الدكتور جاويد رضوان، وهي عيادة معتمدة بشهادة ISO 9001:2015. تقع في 122، Pocket 2، Jasola، بالقرب من مدرسة DAV، وتحصل على تقييمات جيدة من المرضى. يحمل الدكتور رضوان درجتي BDS وMDS وأكمل ماجستيرًا في الزراعة الاستراتيجية بميونخ، ألمانيا، حيث تدرب على يد رائد في زراعة القشرة القاعدية. يتمتع بأكثر من 15 عامًا من الخبرة.\n##specialities\nتقدم العيادة علاج قناة الجذر بلا ألم لإنقاذ الأسنان التالفة، وزراعة الأسنان لكامل الفم للأسنان المفقودة، والزراعة الفردية، والتبييض الاحترافي، وخيارات تقويم متقدمة، وتحسينات الابتسامة بطب الأسنان التجميلي. تدير المجموعة برامج إقامة سريرية في طب الأسنان العام والزراعة.\n##technology\nيوفر التصوير الرقمي رؤية واضحة للأسنان واللثة لتخطيط علاج أفضل، وتهدف العيادة إلى تقديم رعاية أسنان أخلاقية متمحورة حول المريض في بيئة مريحة.\n##international\nتقع Jasola Vihar بالقرب من Indraprastha Apollo Hospital ومحطات مترو Jasola في South Delhi. غالبًا ما يُخطط لعمل زراعة الأسنان وتصميم الابتسامة في عدد قليل من الزيارات.",
	'zemya-ivf-fertility-clinics':
		"##history\nZemya IVF & Fertility Clinics مركز خصوبة يقع في C-10، Green Park Extension، نيودلهي، يُوصف بأنه من أبرز مراكز أطفال الأنابيب في Delhi NCR. يقدم رعاية متعاطفة متمحورة حول المريض ويفيد بمساعدة أكثر من 50,000 زوج. يضم الفريق أخصائيي أطفال أنابيب مدربين عالميًا وأخصائيي أجنة معتمدين من ESHRE، بمن فيهم أخصائية أجنة كبيرة ومديرة مختبر أطفال الأنابيب بخبرة تفوق 15 عامًا في علم الأجنة السريري وتقنيات الإنجاب المساعد.\n##specialities\nتقدم Zemya أطفال الأنابيب وICSI وIUI ورعاية عقم الذكور وتجميد البويضات والحفاظ على الخصوبة تحت سقف واحد، بخطط علاج مخصصة. تغطي صفحات العلاج فيها أطفال الأنابيب وICSI وعقم الذكور بالتفصيل.\n##technology\nتشمل المرافق صالات انتظار واسعة، وغرف تعافٍ خاصة وفاخرة، وغرف عمليات معيارية، ومختبر أطفال أنابيب حديث، ومختبر ذكورة متقدم لفحوصات الخصوبة لدى الرجال، وصيدلية خاصة، ومختبر علم الأمراض، وصالة للمرضى الدوليين، وغرفة استشارة، وقاعة مؤتمرات، وخدمات استشارة عبر الفيديو.\n##international\nGreen Park منطقة جيدة الخدمات في South Delhi، بإمكانية وصول بالمترو وفنادق ومطاعم، والعيادة تضم صالة للمرضى الدوليين.",
	'kokilaben-dhirubhai-ambani-hospital':
		"##history\nبدأ تشغيل مستشفى Kokilaben Dhirubhai Ambani، على طريق Rao Saheb Achutrao Patwardhan Marg في Andheri West (مومباي)، في أوائل 2009 كمستشفى متعدد التخصصات بسعة 750 سريرًا. يخدم مومباي والمناطق المجاورة والمرضى الدوليين، ومعتمد من JCI وNABH وCAP. في 2025، سُمّي Best Hospital – National في ست فئات (متعدد التخصصات، الأورام، الروبوتيات، الأعصاب، جراحة العظام، وإعادة التأهيل) في Financial Express Healthcare Summit and Awards، وحصل على NABH Digital Health Excellence Award.\n##specialities\nيفيد المستشفى بإجراء أكثر من 21,000 عملية سرطان معقدة، وأكثر من 280 زراعة كبد، وأكثر من 3,600 جراحة روبوتية، أجراها فريق من أكثر من 400 طبيب. يُوصف مركزه للجراحة الروبوتية، الذي أُنشئ عام 2012، بأنه الأسرع في الوصول إلى 1,000 جراحة روبوتية خلال 48 شهرًا من الإطلاق. الأورام والأعصاب وجراحة العظام وعلوم القلب والزراعة وإعادة التأهيل من بين نقاط القوة الرئيسية.\n##technology\nيضم المستشفى نحو 180 سرير عناية مركزة وكان موقعًا لعدة سبقيات، منها أول جناح للرنين المغناطيسي أثناء العملية بثلاث غرف في آسيا (IMRIS)، وأول نظام EDGE لعلاج فاريان الإشعاعي في آسيا، وأول جناح لجراحة العمود الفقري بذراع O في الهند. يستخدم دا فينشي Xi وأول نظام جراحة روبوتية Toumai في الهند، الذي يوفر تصويرًا ثلاثي الأبعاد عالي الدقة وقدرة على الجراحة عن بُعد.\n##international\nيُعرف Kokilaben برعايته للمرضى الدوليين، بخدمات الكونسيرج والمساعدة في جميع احتياجات السفر الطبي. Andheri West قريبة من المترو ومطار مومباي الدولي.",
	'p-d-hinduja-hospital':
		"##history\nتأسس مستشفى P. D. Hinduja عام 1951 على يد Parmanand Deepchand Hinduja بالتعاون مع Massachusetts General Hospital، المستشفى التعليمي الرئيسي لكلية الطب بجامعة هارفارد، وانتقل إلى مبنى East Wing في موقع Mahim عام 1963، محولًا نفسه من منشأة عيادات خارجية متواضعة إلى مستشفى متكامل. يقع على طريق Veer Savarkar Marg، بالقرب من Shivaji Park. أصبح أول مستشفى في الهند يحصل على Green and Clean Hospital Platinum Certificate من Bureau Veritas، وفاز بجوائز منها IMC Ramkrishna Bajaj National Award لجودة الرعاية الصحية.\n##specialities\nيقدم المستشفى خدمات في أكثر من 45 تخصصًا باستثناء التوليد، بـ53 سرير عناية مركزة و19 وحدة رعاية نهارية و170 استشاريًا وأكثر من 800 ممرض وموظفين آخرين، إلى جانب مركز للفحص الصحي. كان أول مستشفى خاص في مومباي يجري زراعة كلى من متبرع متوفى وزراعة خلايا جذعية محيطية، وأول مستشفى في الهند يجري عملية فتح قحف والمريض مستيقظ لجراحة الصرع. أمراض القلب والأورام والأعصاب وجراحة العظام من نقاط القوة الرئيسية.\n##technology\nيدير المستشفى دورات DNB في 26 تخصصًا، وبرامج ماجستير ودكتوراه، وكلية تمريض، ودورات صحية مساعدة، ويتعاون مع مؤسسات مثل Hôpitaux Universitaires de Genève وStanford University وHenry Ford Health. معتمد من NABH.\n##international\nيضم المستشفى قسمًا مخصصًا لخدمات المرضى الدوليين للمساعدة في تخطيط العلاج وتنسيقه. Mahim مرتبط جيدًا بالقطار والطريق بوسط مومباي والمطار.",
	'fortis-hospital-mulund':
		"##history\nافتتح مستشفى فورتيس، Mulund، عام 2002، وهو مستشفى متعدد التخصصات للرعاية الفائقة بسعة 400 سرير على طريق Mulund–Goregaon Link Road. يُوصف بأنه أول مستشفى في الهند وجنوب آسيا يحصل على اعتماد JCI، والوحيد في غرب الهند بسبع اعتمادات JCI متتالية. كان أول مستشفى في البلاد يحصل على اعتماد NABH لخدمات الطوارئ، وأول مستشفى في الهند يطلق وحدة عناية مركزة إلكترونية. حصل المستشفى على أكثر من 250 جائزة للتميز في الرعاية الصحية.\n##specialities\nيضم فورتيس Mulund أكبر مركز لزراعة الأعضاء المتعددة في ولاية Maharashtra، يغطي الكلى والكبد والقلب ونخاع العظم. كان الأول في غرب الهند الذي أكمل أكثر من 100 زراعة قلب في أربع سنوات فقط وأكمل زراعة نخاع العظم رقم 100 عام 2024. يُعد برنامجه للأعصاب، بتصوير عصبي متقدم ووحدات عناية عصبية حرجة، من الأفضل في الهند، ويقدم أيضًا علوم القلب والأورام وأمراض الكلى والمسالك البولية وجراحة العظام وأمراض الجهاز الهضمي والطوارئ والرعاية الحرجة ورعاية الأمومة.\n##technology\nيضم المستشفى 108 أسرّة عناية مركزة، وست وحدات مخصصة لزراعة نخاع العظم، ومركز صدمات من المستوى الأول. تستخدم الأورام مسرّع Versa HD الخطي، والمستشفى من بين قلة في البلاد بهذه المنصة العلاجية الإشعاعية.\n##international\nيدير فورتيس Mulund International Patient Unit على مدار الساعة، يدعم المرضى والعائلات طوال الرحلة الطبية. يقع في الضواحي الشرقية لمومباي، بالقرب من محطة سكة حديد Mulund.",
	'jaslok-hospital':
		"##history\nتأسس Jaslok Hospital & Research Centre، على طريق Dr. G. Deshmukh Marg في Peddar Road، على يد المحسن Seth Lokoomal Chanrai والجراح Shantilal Jamnadas Mehta، وافتتحته رئيسة الوزراء إنديرا غاندي في 6 يوليو 1973. إنه أحد أقدم المستشفيات الخيرية المتعددة التخصصات للرعاية المتخصصة في الهند، واحتفل بـ50 عامًا من الخدمة بجائزة Navbharat Healthcare عام 2022.\n##specialities\nيضم المستشفى نحو 50 تخصصًا وقرابة 20 عيادة متخصصة، بأكثر من 350 سريرًا منها أكثر من 75 سرير عناية مركزة. أجرى أول زراعة كلى في مستشفى خاص في الهند عام 1974، وأطلق أول قسم مسالك بولية خاص في الهند، وحقق أول زراعة كبد خاصة في مومباي عام 1998 وأول زراعة كبد للأطفال في غرب الهند. أدخل أول كاميرا غاما بثلاثة كاشفات وكاميرا قلب بالحالة الصلبة في الهند، وكان الأول في مومباي بتخطيط صدى القلب ثنائي الأبعاد والدراسات الكهربية والدعامات المطلقة للدواء. في طب الإنجاب، يفيد بأول نقل مدعوم بالكيمة في العالم في أطفال الأنابيب، وفاز بجائزة أفضل عيادة أطفال أنابيب في ET Healthcare Fertility Awards عام 2019.\n##technology\nالمستشفى معتمد من NABH (الإصدار الخامس) وNABL، ويحمل شهادات ISO 9001 و14001 و45001، إلى جانب شهادة التميز في التمريض ولجنة الأخلاقيات NABH.\n##international\nيقدم Jaslok دعمًا للمرضى الدوليين، بما فيه استشارة قبل الوصول وتخطيط التكلفة بالاستشارة عن بُعد وخطط علاج مفصلة، والمساعدة في التأشيرة والسفر. يقع جنوب مومباي، بالقرب من Mahalaxmi.",
	'nanavati-max-super-speciality-hospital':
		"##history\nافتُتح مستشفى Nanavati Max Super Speciality في Vile Parle في نوفمبر 1950 على يد أول رئيس وزراء للهند، جواهر لال نهرو، وباركه المهاتما غاندي، وفتح أبوابه للمرضى عام 1951. كان ركيزة للرعاية الصحية في مومباي لأكثر من 70 عامًا، وهو الآن جزء من Max Healthcare. يضم 350 سريرًا وأكثر من 350 استشاريًا وأكثر من 100 طبيب مقيم ونحو 475 موظف تمريض ونحو 1,500 موظف.\n##specialities\nيضم المستشفى 55 قسمًا متخصصًا ومراكز تميز في أمراض القلب والأورام وأمراض الكلى وجراحة العظام وجراحة العمود الفقري والأعصاب والسمنة وجراحة الجهاز الهضمي. يقدم أيضًا العلاج الطبيعي والجلدية والجراحة التجميلية وأعصاب الأطفال والطب التنفسي وجراحة العمود الفقري طفيفة التوغل وزراعة نخاع العظم والتوليد وأمراض النساء ورعاية الجهاز الهضمي والكبد والجراحة العامة والمنظارية واستبدال المفاصل والأعصاب. أطلق مركزه للجراحة الروبوتية عام 2019 وأدخل علاج قلم ومضخة الأبومورفين لمرض باركنسون بالتعاون مع King's College London عام 2018.\n##technology\nيمتد مركز التصوير على أكثر من 10,000 قدم مربع برنين مغناطيسي واسع الفتحة 3 تسلا وماسح PET-CT بـ64 شريحة بقدرة قلبية. المستشفى معتمد من NABH وNABL، وفاز بجوائز منها أفضل مستشفى لسلامة المرضى (2021) ومستشفى العام في زراعة الأعضاء (2024).\n##international\nيضم المستشفى International Patient Desk مخصصًا يقدم استقبالًا ومغادرة مجانية من المطار، ومساعدة في التأشيرة، وتنسيق تأمين السفر الطبي، ومترجمين فوريين وتحريريين، وصرف عملات، ووجبات مخصصة. يقع في Vile Parle West، بالقرب من مطاري مومباي المحلي والدولي.",
	'apollo-hospitals-greams-road':
		"##history\nأُطلق Apollo Hospitals، Greams Road، عام 1983 على يد الدكتور براثاب سي. ريدي كأول مستشفى خاص يُدار باحترافية في الهند بسعة 150 سريرًا، وكونه أول مستشفى مساهم في البلاد، لعب دورًا مهمًا في تحويل الرعاية الصحية الخاصة. حصل الدكتور ريدي على بادما فيبهوشان وجوائز إنجاز مدى الحياة من ثلاث دور إعلامية. اليوم يضم المستشفى 550 سريرًا، ومعتمد من JCI وNABH، ويُعتبر على نطاق واسع من أفضل مستشفيات الهند للمرضى الدوليين.\n##specialities\nيضم المستشفى أكثر من 12 مركز تميز، بما فيها Apollo Heart Institute وInstitute of Liver Sciences وInstitute of Neurosciences وInstitute of Colorectal Surgery وInstitute of Robotic Surgery. يغطي برنامج الزراعة فيه الكبد والكلى والقلب والرئة، بإنجازات منها أول زراعة بنكرياس ناجحة في الهند وأول زراعة مشتركة en-bloc للقلب والكبد في آسيا. كان الأول في الهند الذي أدخل رأب الأوعية التاجية والعلاج الإشعاعي المجسم والجراحة الإشعاعية لأورام الدماغ.\n##technology\nتشمل التقنية نظام دا فينشي الجراحي الروبوتي، وExcelsiusGPS لجراحة العمود الفقري، وTrueBeam STx للعلاج الإشعاعي، وأول CyberKnife في الهند، واستخدام PET-CT بـ64 شريحة في جنوب شرق آسيا. يُوصف مركز العلاج بالبروتون بأنه الأول في الهند والأكثر تقدمًا في جنوب آسيا.\n##international\nاعتُرف بأبولو تشيناي كأكثر شركة واعدة في الخدمات الطبية الدولية (MT India Healthcare Awards، 2023). يقع على Greams Lane، بالقرب من Greams Road، وسط تشيناي، قرب الفنادق.",
	'miot-international':
		"##history\nأسس Padmashri الأستاذ الدكتور P. V. A. Mohandas معهد MIOT الدولي، Madras Institute of Orthopaedics and Traumatology، في 12 فبراير 1999 كمستشفى بسعة 70 سريرًا يركز على جراحة العظام والصدمات. أجرى الدكتور Mohandas أول عملية استبدال ورك في الهند وحصل على Padmashri عام 1992 لريادته في استبدال المفاصل. تطور المستشفى إلى منشأة للرعاية الفائقة بسعة 1,000 سرير في Manapakkam بـ63 تخصصًا و21 غرفة عمليات، يستقبل مرضى من أكثر من 130 دولة.\n##specialities\nصنّف Outlook Health قسم جراحة العظام واستبدال المفاصل في MIOT الأول في الهند، بأكثر من 40,000 عملية استبدال ورك وركبة وطرف علوي. من الإنجازات أول جراحة بثقب المفتاح، وأول زراعة كلى عبر فصائل الدم مختلفة في الهند، وأول زراعة نخاع عظم شبه متطابقة في الهند، وأول تركيب لنظام TrueBeam STx العلاجي الإشعاعي في آسيا والمحيط الهادئ. منذ 2012، يضم MIOT International Centre الأورام والعلاج الإشعاعي للأورام ومركز زراعة الكبد ومركز زراعة نخاع العظم، إلى جانب أمراض القلب وأمراض الكلى وجراحة الأعصاب والجراحة التجميلية وطب الأطفال والتوليد.\n##technology\nالمستشفى معتمد من NABH وNABL وفاز بجوائز منها Times Healthcare Legends in Orthopaedics وأفضل مستشفى متعدد التخصصات في تشيناي (2018)، وجائزة Radio City ICON (2019)، وجوائز Times Healthcare Achievers (2020).\n##international\nيقدم MIOT خطابات دعوة للتأشيرة، ونقلًا مجانيًا من المطار، ودعم مترجمين فوريين متعددي اللغات. يقع على Mount Poonamallee Road، ليس بعيدًا عن مطار تشيناي.",
	'gleneagles-global-health-city':
		"##history\nGleneagles Global Health City في Perumbakkam (تشيناي) جزء من IHH Healthcare وأحد أكبر مستشفيات الهند لزراعة الأعضاء المتعددة والرعاية الفائقة، على حرم بمساحة 21 فدانًا. أجرى معهده لأمراض الكبد والزراعة، الذي أنشأه الأستاذ محمد ريلا عام 2009، أكثر من 1,500 زراعة كبد ويُعتبر من أكبر برامج زراعة الكبد في الهند. أجرى الأستاذ ريلا أكثر من 4,000 زراعة كبد ومدرج في Guinness Book of Records لزراعة كبد لرضيع عمره خمسة أيام.\n##specialities\nيضم المستشفى أكثر من 40 تخصصًا ومعترف به دوليًا في زراعة الأعضاء والأورام وأمراض الكبد والأعصاب ورعاية الصدمات. يُجري زراعات الكبد والكلى والقلب والرئة ونخاع العظم، ويفيد بأنه كان الأول في جنوب الهند الذي أجرى خمس زراعات أعضاء في يوم واحد، والأول في الهند الذي أجرى زراعة كبد متبادلة للبالغين وزراعة كبد مقسّم، والأول في الهند الذي زرع رئة اصطناعية وأجرى زراعة رحم. يُعتبر برنامجه لزراعة الرئة من الأفضل في الهند، ويُجري زراعات الكبد بالتعاون مع King's College Hospital بلندن.\n##technology\nيفيد المستشفى بسعة نحو 1,000 سرير، ومعتمد من NABH وNABL، بشهادة حلال للطعام.\n##international\nيهدف المستشفى إلى تقديم مرافق تلبي المعايير الدولية بأسعار تنافسية، خاصةً لزراعة الأعضاء المتعددة. تقع Perumbakkam جنوب تشيناي بالقرب من ممر تكنولوجيا المعلومات.",
	'fortis-malar-hospital':
		"##history\nتأسس مستشفى فورتيس مالار في Adyar (تشيناي) عام 1992 باسم Malar Hospital وانضم إلى فورتيس هيلث كير عام 2007. إنه مستشفى متعدد التخصصات للرعاية المتخصصة بسعة 180 سريرًا، يقدم رعاية في أكثر من 40 تخصصًا. يُعرف بمركزه Fortis Centre for Heart Failure and Transplant، الذي يُوصف بأنه أول مركز شامل في الهند لإدارة فشل القلب.\n##specialities\nيغطي البرنامج القلبي للمستشفى أمراض القلب التداخلية والتوغلية وغير التوغلية والأطفال وجراحة الأوعية القلبية وزراعة القلب. أكمل المركز أكثر من 50 زراعة قلب، وزرعات LVAD طويلة الأمد، ودعم ECMO الوريدي الشرياني لفشل القلب الحرج، ويُنسب إليه أول زراعتي Heartmate II LVAD وHVAD ناجحتين في الهند. الدكتور K. R. Balakrishnan، مدير علوم القلب، يتمتع بأكثر من 30 عامًا من الخبرة، أجرى أكثر من 16,000 عملية قلب، وحصل على FICCI Special Jury Award. يقدم المستشفى أيضًا الأعصاب وجراحة الأعصاب وجراحة العظام وأمراض الكلى وأمراض النساء وأمراض الجهاز الهضمي والمسالك البولية وطب الأطفال ورعاية السكري.\n##technology\nالمستشفى معتمد من NABH. تختلف أرقام سعة الأسرّة حسب المصدر، لذا يجب على المرضى تأكيد السعة الحالية عند التخطيط.\n##international\nيعالج المستشفى مرضى من الخارج؛ شملت حالة حديثة زراعة قلب ناجحة لمواطن باكستاني يبلغ 40 عامًا. Adyar منطقة سكنية هادئة جنوب تشيناي.",
	'kauvery-hospital':
		"##history\nKauvery Hospital في Alwarpet، 81، TTK Road، مستشفى متعدد التخصصات في وسط تشيناي، جزء من مجموعة Kauvery، التي تضم أكثر من 2,000 سرير في 10 مواقع بولايتي Tamil Nadu وKarnataka. تصف Newsweek المستشفى بأنه من أفضل 20 مستشفى في الهند، وقضى 25 عامًا في بناء شبكة من الجراحين المدربين دوليًا. تحمل مستشفياته في Alwarpet وVadapalani اعتماد JCI، الذي يُوصف بأنه الشبكة الوحيدة في الهند بازدواجية اعتماد JCI الإصدار الثامن.\n##specialities\nتضم Kauvery مراكز تميز في علوم القلب والأعصاب وأمراض الجهاز الهضمي وزراعة الأعضاء وجراحة العظام وصحة المرأة. يركز Kauvery Heart Institute في Alwarpet على رأب الأوعية المعقد وImpella والمجازة الهجينة وزراعة القلب. كُرّم فريقه لزراعة القلب والرئة، المكوّن من جراحي زراعة وأطباء قلب لفشل القلب وأطباء رئة للزراعة وأطباء تخدير الصدر وأطباء عناية مركزة وأخصائيي دوران خارج الجسم ومنسقين، من قبل Tamil Nadu State Transplant Authority (TRANSTAN) عام 2023.\n##technology\nيقدم Kauvery Institute of Robotic Surgery جراحة روبوتية بنظام دا فينشي في الأورام والمسالك البولية وجراحة الجهاز الهضمي والقولون والمستقيم والقلب، وجراحة الكبد وزراعة الكلى. يضم المستشفى نحو 300 سرير في مبنى من سبعة طوابق بالقرب من جسر Alwarpet، ومعتمد من NABH.\n##international\nما يجذب العديد من المرضى الدوليين إلى Kauvery هو فريقه الطبي عالي التخصص. تقع Alwarpet في موقع مريح بوسط تشيناي، بالقرب من الفنادق والمطاعم.",
	'manipal-hospital-old-airport-road':
		"##history\nأُطلق Manipal Hospital، Old Airport Road، في بنغالورو عام 1991 كأول مستشفى مساهم في المدينة، وأصبح المستشفى الرائد لشبكة Manipal Hospitals وحجر الأساس لـManipal Education and Medical Group. سُمّي Best Multispeciality Hospital (Private) في The Week Health Summit 2025 وBest Multi-Speciality Hospital in Bengaluru في The Week Best Hospitals Awards 2024، وفاز بـGolden Peacock National Quality Award عام 2005. معتمد من NABH وJCI.\n##specialities\nيقدم المستشفى أكثر من 60 تخصصًا فائقًا بمراكز تميز في الأورام وعلوم القلب والأعصاب وأمراض الجهاز الهضمي وجراحة العظام وزراعة الأعضاء. إنه مركز راسخ لزراعة الأعضاء المتعددة ببرامج شاملة للكلى والكبد والبنكرياس والقلب والرئة ونخاع العظم، ويُعرف بتبنيه المبكر في الهند لزراعة الكلى المدعومة بالروبوت. برنامج الزراعة في الشبكة الأوسع من بين الأكبر في البلاد.\n##technology\nيضم المستشفى نحو 600 سرير أو أكثر، بما فيها 144 سرير عناية مركزة، و20 غرفة عمليات معيارية، إلى جانب رعاية متقدمة للسرطان ووحدات زراعة الأعضاء.\n##international\nيخدم المستشفى مرضى من أكثر من 80 دولة، ويقدم دعمًا شاملًا: استشارة قبل الوصول وتخطيط العلاج بالاستشارة عن بُعد، والمساعدة في التأشيرة والسفر بخطابات دعوة للتأشيرة الطبية، والاستقبال والمغادرة من المطار، والإقامة، والترجمة والمترجمين الفوريين متعددي اللغات. يقع على HAL Old Airport Road.",
	'sakra-world-hospital':
		"##history\nأُطلق مستشفى Sakra World في بنغالورو في فبراير 2014، ويُوصف بأنه أول مستشفى متعدد التخصصات ياباني في الهند وأول مستشفى في الهند بـ100٪ استثمار أجنبي مباشر، تملكه وتديره شراكة بين Toyota Tsusho وSecom Hospitals اليابانية، بمشاركة Kirloskar عند الإطلاق. يجمع بين قوى الهند واليابان، وتمزج بروتوكولاته التمريضية بين الممارسة الهندية واليابانية. حصل على Award for Excellence in Healthcare من Indian Business Awards، وتقديرًا وطنيًا من وزارة الصحة ورعاية الأسرة، وأول National Award for Laboratory Excellence من QCI. حصل أيضًا على اعتماد AACI، مع الإعلان عن مستشفى ثانٍ بسعة 500 سرير.\n##specialities\nيقدم المستشفى الأعصاب وأمراض القلب وجراحة العظام والتوليد وأمراض النساء وعلوم الكلى وعلوم إعادة التأهيل وطب الأطفال وجراحة العمود الفقري والأشعة وعلم النفس السريري والطب الباطني وأنف وأذن وحنجرة وجراحة الرأس والرقبة والسرطان واضطرابات الدم والجراحة التجميلية والطب التنفسي وأمراض الروماتيزم والغدد الصماء وطب الأسنان والجلدية والطب النفسي وطب العيون والرعاية الحرجة وطب الألم والمزيد. يُعرف بأمراض القلب وجراحة العظام والأعصاب وزراعة الأعضاء. يُعتبر Sakra Institute of Rehabilitation Sciences أكبر مركز إعادة تأهيل في آسيا والأول بشهادة جودة عالمية.\n##technology\nيضم المستشفى 350 سرير إقامة، بتصوير يشمل الرنين المغناطيسي والأشعة المقطعية متعددة الكاشفات والموجات فوق الصوتية ثلاثية وربعية الأبعاد والأشعة السينية الرقمية وOPG وقياس كثافة المعادن العظمية.\n##international\nيهتم قسم مخصص لخدمات المرضى الدوليين بالمرضى والمرافقين القادمين من الخارج، بترتيبات التأشيرة، ونقل المطار، والإقامة، والترجمة اللغوية، وإدارة رعاية شخصية. يقع المستشفى على Outer Ring Road، بالقرب من Marathahalli وBellandur.",
	'narayana-institute-of-cardiac-sciences':
		"##history\nبدأ تشغيل Narayana Institute of Cardiac Sciences عام 2000 كجزء من NH Health City في Bommasandra (بنغالورو) على يد جراح القلب ديفي شيتي، مؤسس Narayana Health. إنه المركز القلبي الرائد لـNarayana Health وأحد أكبر مستشفيات القلب في العالم، جزء من حرم يُوصف بأنه أحد أكبر مواقع رعاية القلب في العالم. أجرى المعهد أكثر من 100,000 إجراء قلبي ويضم فريقًا من أكثر من 250 طبيب قلب ومتخصص قلبي. معتمد من JCI وNABH.\n##specialities\nيتخصص المعهد في جراحة القلب وزراعته، ويقدم أيضًا خدمات دراسات كهربية القلب، وزراعة أجهزة المساعدة البطينية اليسرى (LVAD)، وزراعة الصمام الأبهري عبر القسطرة (TAVI)، وبرنامجًا لأمراض القلب البنيوية. يُجري أكثر من 40 جراحة قلب يوميًا، منها نحو 16 جراحة قلب للأطفال.\n##technology\nتضم المنشأة نحو 20 غرفة عمليات قلبية، منها غرفتان روبوتيتان متقدمتان، وعدة مختبرات قسطرة رقمية، بما فيها مختبر هجين للإجراءات التداخلية وجراحات القلب المعقدة. تضم نحو 200 سرير عناية مركزة للرعاية بعد الجراحة.\n##international\nيبعد المعهد نحو 50 كم عن مطار Kempegowda الدولي، مما يجعله مريحًا للمرضى القادمين من مناطق أخرى في الهند ومن الخارج. يقع على Hosur Road، بالقرب من Electronic City.",
	'fortis-hospital-bannerghatta-road':
		"##history\nافتتح مستشفى فورتيس، Bannerghatta Road، عام 2006، وهو المستشفى الرائد متعدد التخصصات لفورتيس هيلث كير في جنوب الهند، مقابل IIM Bangalore. معتمد من NABH (أربع مرات) وJCI (خمس مرات)، ويُقال إنه أول مستشفى في Karnataka يحصل على اعتماد JCI. فاز بجوائز منها جوائز AHPI، وNational Energy Conservation Award (2014)، وAsian Patient Safety Award، واعتماد دولي للسياحة الطبية للتميز في الرعاية، وصُنّف ضمن أفضل مستشفيات بنغالورو المتعددة التخصصات من The Week.\n##specialities\nيقدم المستشفى رعاية متخصصة فائقة في نحو 40 مجالًا طبيًا، بمراكز تميز في أمراض القلب وجراحته والأعصاب وجراحتها والأورام وجراحة العظام وزراعة الأعضاء وأمراض الجهاز الهضمي وطب الأطفال والرعاية الحرجة. يقدم قسم الأورام فيه علاجًا إشعاعيًا متقدمًا وعلاجًا كيميائيًا وهيئات أورام وزراعة نخاع عظم، وجراحة سرطان روبوتية وHIFU لسرطان البروستاتا، بدعم من PET-CT وPET-MR ورنين مغناطيسي 3T وتشخيص جزيئي. يشمل برنامجه القلبي رأب الأوعية والمجازة وإصلاح الصمامات ودراسات كهربية القلب وجراحة القلب الهجينة وزراعات القلب والرئة، وFortis Institute of Robotic Surgery مركز تميز.\n##technology\nيضم المستشفى نحو 280 سريرًا وأكثر من 150 طبيبًا و800 موظف شبه طبي، بخدمات طوارئ وزراعة أعضاء ورعاية وقائية.\n##international\nيقدم فورتيس Bannerghatta Road خدمات للمرضى الدوليين بمساعدة في التأشيرة الطبية ومترجمين ودعم كونسيرج، ويفيد بدعم مرضى من أكثر من 175 دولة. يقع على Bannerghatta Road، جنوب بنغالورو.",
	'aster-cmi-hospital':
		"##history\nمستشفى Aster CMI في Hebbal (بنغالورو) جزء من Aster DM Healthcare، إحدى أكبر شبكات الرعاية الصحية في آسيا، العاملة في تسع دول. تختلف المصادر بشأن سنة افتتاحه، لذا يُفضَّل وصفه بأنه مستشفى من عقد 2010. معتمد من NABH وNABL ويضم قرابة 500 سرير، من الرعاية الأولية إلى الفائقة. كان أول مستشفى في بنغالورو يُختار مركزًا لزراعة الكلى في ولاية Karnataka، وأول مستشفى في Karnataka يحصل على شهادة FPID (الولايات المتحدة) كمركز تميز لنقص المناعة الأولي.\n##specialities\nيقدم Aster CMI مراكز تميز في علوم القلب والأعصاب وأمراض الجهاز الهضمي والرعاية الكبدية المتكاملة وزراعة الأعضاء والمسالك البولية وأمراض الكلى وجراحة العظام وصحة المرأة وصحة الطفل والمراهق، بأكثر من 38 تخصصًا تحت سقف واحد. أكمل برنامج الزراعة فيه أكثر من 1,000 زراعة كلى إجمالًا، منها 54 زراعة كلى روبوتية حتى الآن باستخدام الروبوت الجراحي دا فينشي. يقدم Aster International Institute of Oncology العلاج بالبروتون والجراحة الروبوتية وHIPEC والتنميط الجزيئي للأورام.\n##technology\nيقع المستشفى في منطقة Hebbal على طريق المطار، وصُنّف قسمه للمسالك البولية والكلى ضمن الأفضل في بنغالورو في استطلاع الرعاية الحرجة لـTimes of India.\n##international\nللمرضى الدوليين، يقدم Aster CMI تنسيقًا مخصصًا، ونقل المطار، ومترجمين بلغات أجنبية، ومساعدة في التأشيرة. تقع Hebbal على الطريق بين وسط بنغالورو ومطار Kempegowda الدولي.",
	'apollo-hospitals-jubilee-hills':
		"##history\nأُسس Apollo Hospitals، Jubilee Hills، عام 1988، وهو المستشفى الرائد لأبولو في حيدر آباد ويحمل اعتماد JCI. كرّمته حكومة الهند كمستشفى رائد للسياحة الطبية، وحصل على FICCI Healthcare Excellence Award. أدخل أول ماسح PET-CT في الهند عام 2005، وأجرى أول رأب أوعية تاجية في الهند باستخدام دعامة قابلة للامتصاص الكامل، وأجرى أكثر من 150,000 جراحة قلب بمعدل نجاح مُبلغ عنه يفوق 99٪. أكمل أيضًا أكثر من 700 زراعة قوقعة.\n##specialities\nيدير المستشفى 12 مركز تميز. يضم مركز علوم القلب ثلاث مختبرات قسطرة وغرف عمليات قلبية مخصصة، مع جراحة قلب مدعومة بالروبوت وTAVI وتدخلات تاجية معقدة. يعتمد مركز السرطان على 35 عامًا من الخبرة ويقدم جراحة أورام روبوتية. الأعصاب مجهزة بجناح رنين مغناطيسي أثناء العملية وملاحة عصبية وروبوتات العمود الفقري. يدير فريق الزراعة زراعات الكبد والكلى والقلب ونخاع العظم، وأجرت مجموعة أبولو أكثر من 43,000 زراعة أعضاء.\n##technology\nيضم المستشفى نحو 550 سريرًا ومعتمد من JCI وNABH وNABL. يقع في Road No. 72، Film Nagar، Jubilee Hills.\n##international\nيتعامل المستشفى مع أكثر من 800 استشارة للمرضى الدوليين شهريًا، بمرضى من دول منها الولايات المتحدة والإمارات وتنزانيا وكينيا وعُمان. يساعد فريق مخصص لخدمات المرضى الدوليين في التأشيرات الطبية وترتيبات السفر والإقامة والترجمة.",
	'continental-hospitals':
		"##history\nتأسس Continental Hospitals في أبريل 2013 على يد الدكتور غورو إن. ريدي في Financial District بحيدر آباد (Nanakramguda، Gachibowli). إنه مستشفى بسعة 585 سريرًا يمتد على 18 طابقًا و1.4 مليون قدم مربع، معتمد من JCI وNABH وNABL، وأول مستشفى فائق التخصص في الهند مؤهل بشهادة LEED، بغرف عمليات خضراء وNICU وPICU من المستوى الثالث. فاز بجائزة ASSOCHAM 2022 كأفضل مستشفى في الهند في تبني التقنية.\n##specialities\nيقدم المستشفى أكثر من 50 تخصصًا ويُعرف بزراعة الأعضاء المعقدة وعلوم القلب والأعصاب والأورام وعلوم المعدة وجراحة العظام. في أبريل 2023، أجرى فريق من الجراحين بقيادة الدكتور برادييب راشاكوندا وبإشراف الدكتور سوذير سريفاستافا أول جراحة مجازة تاجية (CABG) مدعومة بالروبوت في الهند باستخدام روبوت SSI Mantra. يدير قسم الزراعة فيه زراعات الكبد والكلى والقلب والرئة ونخاع العظم، بدعم من عناية مركزة متقدمة وإعادة تأهيل بعد الزراعة.\n##technology\nيضم المستشفى 16 غرفة عمليات خضراء معيارية و90 سرير عناية مركزة بغرفة فردية، بجراحين مدربين على منصة دا فينشي ومنصات روبوتية أخرى.\n##international\nيضم Continental منطقة مخصصة للمرضى الدوليين وصالة للفحص الصحي. يقع في Financial District، بالقرب من ممر تكنولوجيا المعلومات في حيدر آباد، على بُعد نحو 30–45 دقيقة من المطار.",
	'yashoda-hospitals-somajiguda':
		"##history\nYashoda Hospitals، Somajiguda، هو أول مستشفى في مجموعة Yashoda، بدأ عام 1994 بعد عيادة صغيرة افتتحها الدكتور جي. سوريندار راو عام 1989. عبر ثلاثة عقود، توسعت المجموعة بفروع في Somajiguda وSecunderabad وMalakpet وHitec City. كُرّمت وحدة Somajiguda كمستشفى صديق للمريض من AHPI، وصُنّفت المجموعة الأولى في زراعة الأعضاء من المتوفين من قبل حكومة الهند والأولى بين المستشفيات المتعددة التخصصات في جوائز Times Healthcare Achievers.\n##specialities\nيضم المستشفى أكثر من 400 سرير ونحو 250 طبيبًا و500 ممرض. تغطي مراكز التميز فيه جراحة القلب والصدر والأعصاب والسرطان وزراعة الكبد والأعضاء المتعددة والعظام والمفاصل وأمراض الكلى وعلوم الروبوتات وجراحة العمود الفقري ورعاية الأم والطفل والخصوبة، إلى جانب قائمة واسعة جدًا من الأقسام من أنف وأذن وحنجرة وأمراض النساء إلى الجراحة التجميلية والطب النووي والجراحة البارياتريكية. من إنجازات الزراعة في المجموعة أول زراعة رئة في الولايات الناطقة بالتيلوغو (2012) وزراعة قلب ورئة مشتركة (2017).\n##technology\nيعمل المختبر وخدمات التشخيص والصيدلية على مدار الساعة. المستشفى معتمد من NABH وهو الأول في المنطقة الذي أدخل الجراحة الروبوتية.\n##international\nتقدم Yashoda خدمات للمرضى الدوليين، ببرنامج زراعة يصنَّف ضمن أفضل برامج زراعة الأعضاء المتعددة في الهند، بفريق متعدد التخصصات لغسيل الكلى وأمراض الكبد والكلى وزراعات الأطفال. تقع Somajiguda على طريق Raj Bhavan Road، وسط حيدر آباد.",
	'global-hospitals-hyderabad':
		"##history\nGleneagles Global Hospitals في Lakdi-ka-pul، المعروف بـGlobal Hospitals، كان أول مستشفى Gleneagles Global يُفتتح في حيدر آباد وينتمي إلى Global Hospitals Group، التي أسسها الدكتور K. Ravindranath عام 1999. كان رائدًا في أول زراعة قلب في ولايتي أندرا براديش وتيلانغانا السابقتين، وأجرى أول زراعة نخاع عظم في المنطقة وأول زراعة كلى توأمية، ويفيد بأول زراعة كبد مقسّمة ومساعدة ناجحة في الهند. صُنّف ثاني أفضل مستشفى متعدد التخصصات في حيدر آباد وضمن أفضل 10 في جنوب الهند وفق استطلاع Times of India لعام 2021.\n##specialities\nيُعرف المستشفى بزراعة الكبد والكلى والقلب والرئة، ويقدم أيضًا أمراض الكبد والكلى والجراحة البارياتريكية وأمراض الجهاز الهضمي وزراعة الأعضاء المتعددة والجراحة التجميلية والترميمية والأورام وعلوم القلب وطب الأطفال والطب النفسي والغدد الصماء وأنف وأذن وحنجرة وجراحة العظام وجراحة العمود الفقري وعلوم المعدة والجراحة العامة والمنظارية والطب التنفسي.\n##technology\nيضم المستشفى نحو 150 سريرًا وست غرف عمليات، بقدرة روبوتية وطفيفة التوغل، وعدة وحدات عناية مركزة، بما فيها العناية الجراحية والقلبية والانتقالية والكبدية ووحدات ما بعد الزراعة. معتمد من NABH وNABL.\n##international\nيقدم المستشفى دعمًا للمرضى الدوليين من خلال مجموعة Gleneagles Global. Lakdi-ka-pul موقع مركزي في حيدر آباد، بالقرب من محطة مترو Lakdi-ka-pul.",
	'kims-hospitals-secunderabad':
		"##history\nافتتح KIMS Hospitals، Secunderabad، عام 2004 كمستشفى رائد لمجموعة Krishna Institute of Medical Sciences، وهو مستشفى للرعاية المتخصصة والفائقة بسعة 1,000 سرير، أحد أكبر المستشفيات الخاصة في الهند. أسس المجموعة عام 2000 جراح القلب والصدر الدكتور Bhaskar Rao Bollineni، الذي أجرى أكثر من 30,000 جراحة خلال 25 عامًا وساهم في صياغة مخطط Rajiv Gandhi Aarogyasri عام 2007. تضم المجموعة الآن أكثر من عشرين مستشفى، ومديرها التنفيذي والرئيس التنفيذي هو الدكتور Abhinay Bollineni.\n##specialities\nيقدم المستشفى أكثر من 25 تخصصًا وتخصصًا فائقًا، بما فيها أمراض القلب وأمراض الجهاز الهضمي والكبد والأعصاب وزراعة الأعضاء والأورام وجراحة العظام والمسالك البولية والخصوبة وعلوم الكلى ورعاية الأم والطفل. يعالج مركز الأعصاب فيه أورام الدماغ وتشوهات العمود الفقري والتحفيز العميق للدماغ لمرض باركنسون وإدارة السكتة الدماغية، ويعالج مركز KIMS Advanced Gastroenterology and Endoscopy (KAGE) اضطرابات الجهاز الهضمي المعقدة وأمراض الكبد وإجراءات POEM.\n##technology\nيغطي برنامج الزراعة القلب والرئة والكبد والكلى ونخاع العظم، بما في ذلك التروية المتقدمة خارج الجسم. أكمل مركز زراعة القلب والرئة أول زراعة قلب له عام 2012 ويُجري نحو 75 زراعة قلب ورئة سنويًا، وسجّل المستشفى 1,000 زراعة كلى عام 2019. معتمد من NABH ويحمل شهادة ISO 9001:2015.\n##international\nيقع KIMS Secunderabad على طريق Minister Road، وسط Secunderabad، بالقرب من محطة سكة حديد Secunderabad.",
};
